package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DateTimeZoneMidday;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParser;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class DateTimeFormatter_parseInto_TriageGen2Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant mockInstant;
    private DateTimeParser mockParser;
    private Chronology mockChrono;

    @Before
    public void setUp() {
        // We use a real builder to create a formatter to avoid complex mocking of the internal state
        // but we will mock the ReadWritableInstant to verify side effects.
        mockInstant = mock(ReadWritableInstant.class);
        mockChrono = mock(Chronology.class);
        DateTimeZone mockZone = DateTimeZone.UTC;

        when(mockInstant.getMillis()).thenReturn(0L);
        when(mockInstant.getChronology()).thenReturn(mockChrono);
        when(mockChrono.getZone()).thenReturn(mockZone);
        // Mocking chronology year access
        org.joda.time.LocalDate mockLocalDate = new org.joda.time.LocalDate(2023, 1, 1);
        when(mockChrono.year()).thenReturn(mockChrono); 
        // Note: In real Joda, chrono.year() returns a Field. 
        // For unit testing the logic of parseInto, we will rely on a real formatter instance 
        // and mock the instant.

        formatter = new DateTimeFormatterBuilder()
                .appendLiteral('2')
                .appendInteger()
                .toFormatter();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        formatter.parseInto(null, "2023", 0);
    }

    @Test
    public void testParseInto_Success_Basic() {
        // Using a real formatter with a real instant to ensure internal parser/bucket logic works
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy")
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);
        String text = "2023";
        int position = 0;

        int newPos = realFormatter.parseInto(instant, text, position);

        assertEquals(4, newPos);
        assertEquals(2023, instant.getYear());
    }

    @Test
    public void testParseInto_WithOffsetParsed_True() {
        // Test the branch: if (iOffsetParsed && bucket.getOffsetInteger() != null)
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMddHHmmssZ")
                .withOffsetParsed()
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2023, 1, 1, 0, 0);
        String text = "20230101120000+0200";

        realFormatter.parseInto(instant, text, 0);

        assertEquals(2023, instant.getYear());
        assertEquals(2, instant.getZone().getOffset(instant.getMillis()) / 3600);
    }

    @Test
    public void testParseInto_WithZoneInBucket_NotNull() {
        // Test the branch: else if (bucket.getZone() != null)
        // We use a pattern that might result in a zone if applicable, 
        // but since we can't easily force bucket.getZone() without a complex parser,
        // we use a formatter that naturally handles zones.
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy-MM-dd")
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2023, 1, 1, 0, 0);
        String text = "2023-01-01";

        int newPos = realFormatter.parseInto(instant, text, 0);
        assertEquals(10, newPos);
        assertEquals(2023, instant.getYear());
    }

    @Test
    public void testParseInto_WithSpecificZoneSet() {
        // Test the branch: if (iZone != null)
        DateTimeZone targetZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy")
                .toFormatter()
                .withZone(targetZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2023, 1, 1, 0, 0);
        String text = "2023";

        realFormatter.parseInto(instant, text, 0);

        assertEquals(targetZone, instant.getZone());
    }

    @Test
    public void testParseInto_WithPivotYear() {
        // Test the branch: defaultYear calculation using iPivotYear
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendPattern("yy")
                .withPivotYear(2000)
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2023, 1, 1, 0, 0);
        // "23" with pivot 2000 should be 2023
        String text = "23";

        realFormatter.parseInto(instant, text, 0);

        assertEquals(2023, instant.getYear());
    }

    @Test
    public void testParseInto_WithLocale() {
        // Test the branch: using iLocale in DateTimeParserBucket
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder()
                .appendPattern("MMMM")
                .toFormatter()
                .withLocale(Locale.FRENCH);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2023, 1, 1, 0, 0);
        String text = "janvier";

        realFormatter.parseInto(instant, text, 0);

        assertEquals(1, instant.getMonthOfYear());
    }
}
